<script>(function(){const s=document.getElementById('score-weight'),o=document.getElementById('score-review-estimate');if(!s||!o)return;const b=<?= (int)$reviewOffer['baseline']?>,a=<?= (int)$reviewPreview['evidence_score']?>;function update(){let w=Number(s.value);o.textContent='Score proposé : '+Math.round((b*(100-w)+a*w)/100)+' %';}s.addEventListener('change',update);update();})();</script>
<details class="score-review-evidence"><summary>Voir les critères et les justifications (<?=count($reviewPreview['criteria'])?>)</summary><div class="table-scroll"><table><thead><tr><th>Critère</th><th>Priorité</th><th>État</th><th>Preuve</th></tr></thead><tbody><?php foreach($reviewPreview['criteria'] as $criterion):?><tr><td><?=e($criterion['criterion'])?></td><td><?=e($criterion['priority'])?></td><td><?=e($criterion['status'])?></td><td><?=e($criterion['source'])?></td></tr><?php endforeach;?></tbody></table></div></details>
